    static final class Lending {
        private final java.util.Map<String,String> active = new java.util.HashMap<>();
        synchronized boolean borrow(String copy, String member) {
            return active.putIfAbsent(copy, member) == null;
        }
        synchronized boolean giveBack(String copy, String member) {
            return active.remove(copy, member);
        }
