public class Main {
    static final class Machine {
        private int stock = 1;
        private long credit;
        synchronized void add(long amount) {
            if (amount <= 0) throw new IllegalArgumentException();
            credit = Math.addExact(credit, amount);
        }
        synchronized boolean buy(long price) {
            if (price <= 0 || stock == 0 || credit < price) return false;
            stock--; credit -= price; return true;
        }
    }
    static void test() {
        var m = new Machine(); m.add(100);
        if (!m.buy(60)) throw new AssertionError();
        if (m.buy(40)) throw new AssertionError();
    }
    public static void main(String[] args) { test(); System.out.println("PASS"); }
}

public class Main {
    static final class Parking {
        private final java.util.Set<String> free = new java.util.HashSet<>();
        Parking() { free.add("A1"); }
        synchronized String allocate() {
            if (free.isEmpty()) return null;
            String spot = free.iterator().next(); free.remove(spot); return spot;
        }
        synchronized void release(String spot) {
            if (!"A1".equals(spot) || !free.add(spot)) throw new IllegalStateException();
        }
    }
    static void test() {
        var p = new Parking();
        if (!"A1".equals(p.allocate())) throw new AssertionError();
        if (p.allocate() != null) throw new AssertionError();
        p.release("A1");
        if (p.allocate() == null) throw new AssertionError();
    }
    public static void main(String[] args) { test(); System.out.println("PASS"); }
}

public class Main {
    static final class Lru<K,V> {
        private final java.util.LinkedHashMap<K,V> map;
        Lru(int capacity) {
            if (capacity <= 0) throw new IllegalArgumentException();
            map = new java.util.LinkedHashMap<>(16, 0.75f, true) {
                protected boolean removeEldestEntry(java.util.Map.Entry<K,V> entry) {
                    return size() > capacity;
                }
            };
        }
        synchronized V get(K key) { return map.get(key); }
        synchronized void put(K key, V value) { map.put(key, value); }
    }
    static void test() {
        var c = new Lru<String,Integer>(2);
        c.put("a",1); c.put("b",2); c.get("a"); c.put("c",3);
        if (c.get("b") != null || c.get("a") != 1) throw new AssertionError();
    }
    public static void main(String[] args) { test(); System.out.println("PASS"); }
}

public class Main {
    static final class Bucket {
        final double capacity, rate; double tokens; long last;
        Bucket(int capacity, double rate, long now) {
            if (capacity <= 0 || rate <= 0) throw new IllegalArgumentException();
            this.capacity=capacity; this.rate=rate; tokens=capacity; last=now;
        }
        synchronized boolean allow(long now) {
            if (now < last) throw new IllegalArgumentException("time regression");
            tokens=Math.min(capacity,tokens+(now-last)/1_000_000_000.0*rate);
            last=now;
            if (tokens < 1) return false;
            tokens--; return true;
        }
    }
    static void test() {
        var b = new Bucket(1, 1, 0);
        if (!b.allow(0) || b.allow(0) || !b.allow(1_000_000_000L)) throw new AssertionError();
    }
    public static void main(String[] args) { test(); System.out.println("PASS"); }
}
